ari:C.4.2.text:
\begin{proposition}[The full division identity]\hypertarget{tag-000Q}{}\label{ari:C.4.2}
\StatementRecord{ari:C.4.2}{proved}{000Q}{\SeriesRef{ari:C.1.1}}

Let $\psi_m$ be the standard division polynomial of a smooth
short Weierstrass model, normalized by $\psi_1=1$, $\psi_2=2y$.
On a general equation
$y^2+a_1xy+a_3y=x^3+a_2x^2+a_4x+a_6$, the exact change
$Y=y+(a_1x+a_3)/2$, followed by
$X=x+(a_2+a_1^2/4)/3$, gives a short equation and
$\psi_2=2Y=2y+a_1x+a_3$.
The division functions below are transported by this isomorphism.
For $m\ge2$ and $Q,mQ\ne O$,
\begin{equation}\hypertarget{tag-003N}{}\label{ari:eq:cs-division}
 N(Q)^{m^2}
       =N(mQ)\frac{|\Delta_E|^{(m^2-1)/12}}{|\psi_m(Q)|}.
\end{equation}
For the displayed family this specializes to
\[
 N(P)^4=3^{3/4}|t-1|^{-1/4}N(2P),\qquad
 N(P)^9=16|t|^{-2/3}N(3P).
\]
If $P_t$ has exact order $n$ and $m\ge2$ satisfies
$m\equiv1$ or $-1\pmod n$, then
\begin{equation}\hypertarget{tag-003P}{}\label{ari:eq:cs-torsionvalue}
 N(P_t)^{12}
       =\frac{|\Delta(t)|}{|\psi_m(P_t)|^{12/(m^2-1)}}.
\end{equation}
The positive value on the right is independent of $m$.
\end{proposition}

ari:C.8.1.text:
\begin{proposition}[Three uniform bounds on the elliptic norm]\hypertarget{tag-001J}{}\label{ari:C.8.1}
\StatementRecord{ari:C.8.1}{proved}{001J}{\SeriesRef{ari:eq:ca-sup}, \SeriesRef{ari:eq:ca-exp}}

For every $z\in\C$ and every $\tau$ in the standard modular
fundamental region, we have
\[
 \begin{array}{c|ccc}
 \text{restriction}&T\le2&T\le7/5&T\le11/10\\ \hline
 N(z,\tau)&<17/10&<3/2&<143/100.
 \end{array}
\]
If $\wp_\tau(z)=0$ and $T\ge2$, then $N(z,\tau)<541/500$.
\end{proposition}

ari:C.8.2.text:
\begin{proposition}[The maximum on an explicit local disc]\hypertarget{tag-001Q}{}\label{ari:C.8.2}\hypertarget{tag-01QK}{}\label{fam:src:C.2.2}\label{fam:st:C.2.2}
\StatementRecord{ari:C.8.2}{proved}{001Q}{\SeriesRef{ari:eq:ca-exp}, \SeriesRef{ari:eq:ca-derivatives}, \SeriesRef{ari:eq:ca-GHbounds}, \SeriesRef{ari:eq:ca-H}, \SeriesRef{ari:eq:ca-delta-h}}

If $|\tau-i|\le1/50$ and $\wp_\tau(z)=0$, then
$N(z,\tau)\le\sqrt2$, with equality exactly when $\tau=i$.
\end{proposition}

ari:C.8.3.text:
\begin{proposition}[Comparison of the two local discs]\hypertarget{tag-001R}{}\label{ari:C.8.3}
\StatementRecord{ari:C.8.3}{proved}{001R}{\SeriesRef{ari:eq:ca-derivatives}, \SeriesRef{ari:C.8.2}}

Every complex number $t_0$ with $|t_0-1|\le1/500$ has a
representative $\tau$ with $|\tau-i|<1/50$ and $j(\tau)=1728t_0$.
Consequently every zero of $\wp$ for that modulus satisfies
$N\le\sqrt2$, with equality only for $t_0=1$.
\end{proposition}

ari:C.8.4.text:
\begin{proposition}[The first three normalized duplication steps]\hypertarget{tag-001S}{}\label{ari:C.8.4}
\StatementRecord{ari:C.8.4}{proved}{001S}{\SeriesRef{ari:C.4.2}, \SeriesRef{ari:eq:cs-division}, \SeriesRef{ari:C.3.1}}

Put $u=t-1$. For $n=2^k$, $k=1,2,3$, and $nP\ne O$,
\begin{equation}\hypertarget{tag-002D}{}\label{ari:eq:ca-ladder}
 \left(\frac{N(P)}{\sqrt2}\right)^{n^2}
 =\frac{3^{3/4}}{2n}\,
       \frac{N(nP)|u|^{-1/4}}{|A_k(u)|},
\end{equation}
where
\begin{align*}
 A_1(u)&=1,\qquad A_2(u)=1-5u/27,\\
 A_3(u)&=1-\frac{217}{27}u-\frac{20486}{729}u^2
       +\frac{10910}{19683}u^3
       +\frac{161383}{177147}u^4
       -\frac{245}{14348907}u^5.
\end{align*}
On $|u|\le1/28$ we have $|A_3(u)|\ge1-10|u|$.
For every $k\ge1$, not just these first three steps, define
\[
 E_k(t)=\frac{|\Delta_E|^{(4^k-1)/12}|t-1|^{1/4}}
 {2^{4^k/2}|\psi_{2^k}(P)|}.
\]
Then $(N(P)/\sqrt2)^{4^k}=E_k(t)N(2^kP)|t-1|^{-1/4}$,
and the removable limiting value is
\[
 \lim_{t\to1}E_k(t)=\frac{3^{3/4}}{2^{k+1}}
                 =2^{1-k}\frac{3^{3/4}}4.
\]
\end{proposition}

fam:src:B.1.1.text:
\begin{proposition}\hypertarget{tag-01Q7}{}\label{fam:src:B.1.1}\label{fam:st:B.1.1}
\StatementRecord{fam:src:B.1.1}{proved}{01Q7}{\SeriesRef{fam:src:A.3.1}}

Let $E_\tau=\mathbb C/(\mathbb Z+\tau\mathbb Z)$, $P=[\mu]$, and $L_\mu=\mathcal O_{E_\tau}(P-O)$. The holomorphic map
\[
 [\xi,\eta]\longmapsto[\xi,e^{2\pi i\eta}]
\]
identifies $\mathbb C^2/\Pi_c\Lambda$ with the quotient of $L_\mu^\times$ by the lift
$A(\xi,W)=(\xi+6\mu,e^{2\pi i\beta_c}W)$. Engel's generator, in Definition 2.3 of the attached paper, is its inverse, with translation $-6P$ and multiplier $e^{-2\pi i\beta_c}$. The section $P=[\mu]$ is a generator of the Mordell--Weil group of the stated pointed Weierstrass surface.
\end{proposition}

fam:src:C.1.1.text:
\begin{proposition}[The normalized theta period]\hypertarget{tag-01QH}{}\label{fam:src:C.1.1}\label{fam:st:C.1.1}
\StatementRecord{fam:src:C.1.1}{proved}{01QH}{\SeriesRef{fam:src:B.1.3}}

For the period section identified in Statement \ref{fam:src:B.1.3}, the particular solution
with \((\beta^{\rm part}+\tau)(p_0)=0\) is
\begin{equation}\hypertarget{tag-01P5}{}\label{fam:eq:cd-beta}
 \beta^{\rm part}=\frac{6i}{\pi}\operatorname{Log}
 \frac{\vartheta_1(\mu,\tau)}{2\sqrt3\,\eta_D(\tau)}.
\end{equation}
Here the logarithm is continued on the simply connected uniformizing
half-plane from its cusp expansion. Its special values are
\[
 \mu_0=\frac12-\frac{i\log a}{2\pi},\qquad
 \mu(z_1)=\frac{2-\rho}{3},\qquad \mu(z_2)=\frac{1-i}{2},
\]
\[
 \beta^{\rm part}(z_2)=i\left(\frac32-\frac3\pi\log6\right),
 \qquad \operatorname{Re}\beta^{\rm part}(z_1)=-\frac12.
\]
In particular \(e^{2\pi i\mu_0}=-a\).
\end{proposition}

fam:src:A.5.1.text:
\begin{theorem}\hypertarget{tag-01Q6}{}\label{fam:src:A.5.1}\label{fam:st:A.5.1}\label{wb:pshift:thm:classification}
\StatementRecord{fam:src:A.5.1}{proved}{01Q6}{\SeriesRef{app:rederive:fam-src-A.5.1}; \citet[Theorem~1.4, p.~3]{DuEtAl2026v1}}

Fix the original cusp-regular period solution, the clockwise peripheral marking, the prescribed periodic triangular cusp fan, the affine vectors $(\varepsilon,-\varepsilon')$, and the untwisted cusp collar. For every $c,c'\in\mathcal P$, the constructed compact complex threefolds satisfy
\[
 X_c\simeq X_{c'}\quad\Longleftrightarrow\quad c'-c\in2\mathbb Z.
\]
Every biholomorphism is over the identity of the original $\mathbb P^1$. The proper holomorphic family of their isomorphism classes has parameter $0<|w|<e^{-\pi M}$ and nonzero Kodaira--Spencer class at every point.
\end{theorem}

fam:src:B.2.2.text:
\begin{proposition}\hypertarget{tag-01QC}{}\label{fam:src:B.2.2}\label{fam:st:B.2.2}
\StatementRecord{fam:src:B.2.2}{proved}{01QC}{\SeriesRef{fam:src:A.5.1}, \SeriesRef{fam:src:B.2.1}, \SeriesRef{fam:src:A.2.1}}

For multiplicities $(3,4)$ and $|p|=1$, every admissible discrete member is biholomorphic to one member of \ref{fam:src:A.5.1}, uniquely modulo $2\mathbb Z$. At fixed nonzero admissible Engel parameter $u$ there are exactly two isomorphism classes, exchanged by a positive circuit of $u$ about zero. In the convention that Engel's root generator is the inverse of our clockwise one and his circle class is $d$, the identity of the middle quotient sends
\[
 X_{c+1}\longleftrightarrow X(u;a_0-d/3,\ a_1+d/4).
\]
Reversing both declared root generators reverses these two displayed signs.
\end{proposition}

fam:src:B.2.3.text:
\begin{proposition}[counterexample, with corrected family]\hypertarget{tag-01QD}{}\label{fam:src:B.2.3}\label{fam:st:B.2.3}
\StatementRecord{fam:src:B.2.3}{proved}{01QD}{\SeriesRef{fam:src:A.3.1}, \SeriesRef{fam:src:A.2.1}, \SeriesRef{fam:src:B.2.1}, \SeriesRef{fam:src:A.4.1}; \cite[Remark 8.1]{Engel2026}}

The assertion in \cite[Remark 8.1]{Engel2026} of a global proper family over the original punctured $u$-disc for fixed sphere logarithmic data requires a double-cover qualification. The retained family with such data does not descend through $u=w^2$. It does give a proper holomorphic family on each simply connected $u$-open set, and a global proper family over the punctured $w$-disc as in \ref{fam:src:A.3.1}.
\end{proposition}

fam:src:B.3.1.text:
\begin{proposition}\hypertarget{tag-01QE}{}\label{fam:src:B.3.1}\label{fam:st:B.3.1}
\StatementRecord{fam:src:B.3.1}{proved}{01QE}{\SeriesRef{fam:src:A.1.2}, \SeriesRef{fam:src:A.2.1}, \SeriesRef{fam:src:B.2.1}}

Let $k,l$ be positive integers with $\gcd(3k,4l)=1$, and put $m_1=3k,m_2=4l$. Consider Viaclovsky's sphere members expressed in the same clockwise marking, with $w_j=r_j\varepsilon_j+s_jd$, $\gcd(r_j,m_j)=1$, cusp winding $l_0$, and $p=m_1m_2l_0-m_2r_1-m_1r_2=\pm1$, where $\varepsilon_1=\varepsilon,\varepsilon_2=\varepsilon'$. Two such members are biholomorphic precisely when their multiplicity pair agrees and, for some $a\in\{1,-1\}$ and integer $n=c'-c$,
\[
 p'=ap,\quad r'_j\equiv ar_j\pmod{m_j},\quad
 nr'_1\equiv as_1-s'_1\pmod{k},\quad
 nr'_2\equiv as_2-s'_2\pmod{2l}.
\]
The congruences on $r'_j$ already follow from $p'=ap$. For fixed discrete vectors and cusp collar the identification subgroup is $2kl\mathbb Z$. For fixed admissible $u$ and this multiplicity pair, all the stated sphere translation data give exactly $2kl$ isomorphism classes, permuted in one cycle by a circuit of $u$ about zero.
\end{proposition}

mapsI:src:A.3.1.text:
\begin{proposition}[Two conjugacy classes of real structures]\hypertarget{tag-02PE}{}\label{mapsI:src:A.3.1}
\StatementRecord{mapsI:src:A.3.1}{proved}{02PE}{\SeriesRef{fam:src:B.4.2}, \SeriesRef{fam:src:B.4.1}; \cite[Theorem~3.1, p.~48]{Illman1972}; \cite[Theorem 4.1(1)]{Knudson2004}}

For a real member the antiholomorphic involutions have exactly two
conjugacy classes under holomorphic automorphisms. For any fixed
involutive splitting $\sigma$ they are represented by $\sigma$ and
$\rho(1/2)\sigma$. Every nonempty fixed set is a closed connected
orientable totally real three-manifold with the mod-two homology of
$S^3$. The circle $\rho$ preserves each such fixed set and acts
semifreely on it.
\end{proposition}

mapsI:src:A.3.3.text:
\begin{theorem}[The real three-manifolds]\hypertarget{tag-02PG}{}\label{mapsI:src:A.3.3}
\StatementRecord{mapsI:src:A.3.3}{proved}{02PG}{\SeriesRef{mapsI:src:A.3.2}}

Every nonempty fixed set in Theorem~\ref{mapsI:src:A.3.2} is diffeomorphic to $S^3$.
Its fundamental group is trivial and its integral homology is
$(\Z,0,0,\Z)$. For negative imaginary $w$, the restricted circle action
is the standard semifree action on $S^3$ with fixed circle
$D_2^{\sigma_c}$. For positive imaginary $w$, the nonempty real form
has a free circle action isomorphic, up to circle and orientation
conventions, to the Hopf action.
\end{theorem}

fam:src:D.1.4.text:
\begin{proposition}[The N\'eron--Severi lattice]\hypertarget{tag-01QU}{}\label{fam:src:D.1.4}\label{fam:st:D.1.4}
\StatementRecord{fam:src:D.1.4}{proved}{01QU}{\SeriesRef{fam:src:C.3.1}, \SeriesRef{fam:src:D.1.6}}

For every smooth fibre and every admissible \(c\), its Neron--Severi lattice
is the following explicit subgroup of \(\mathbb Z^6\):
\begin{equation}\hypertarget{tag-01P4}{}\label{fam:eq:cd-NS}
 \left\{E:\ E_{12}-E_{13}\tau+(6E_{23}-E_{14})\mu+
 E_{24}\beta+E_{34}(6\mu^2-\tau\beta)=0\right\}.
\end{equation}
The complex orientation has intersection form
\(E^2=-2\operatorname{Pf}(E)\), where
\(\operatorname{Pf}(E)=E_{12}E_{34}-E_{13}E_{24}+E_{14}E_{23}\).
In particular the invariant class \(\eta=6\gamma\wedge\delta+u\wedge w\)
has \(\int_{F_t}\eta^2=-12\). Its Hermitian form is indefinite.
The fibres with lattice exactly \(\mathbb Z\eta\) have no compact curves
and algebraic dimension zero.
\end{proposition}

fam:src:F.2.2.text:
\begin{theorem}[The maximal domain of proper discontinuity]\hypertarget{tag-01RC}{}\label{fam:src:F.2.2}\label{fam:st:F.2.2}
\StatementRecord{fam:src:F.2.2}{proved}{01RC}{\SeriesRef{fam:eq:F-g}}

The set $\mathcal O$ is the largest $\Gamma$-invariant open subset of
$\mathcal D$ on which the action is properly discontinuous.  It is also
the largest such open subset for $P_{\mathbb Z}$.  Each sign region is
a complex manifold in the analytic topology, and its quotient by either
discrete group is a Hausdorff complex analytic orbifold.
\end{theorem}

fam:src:F.2.3.text:
\begin{proposition}[A global chart for positive periods]\hypertarget{tag-01RD}{}\label{fam:src:F.2.3}\label{fam:st:F.2.3}
\StatementRecord{fam:src:F.2.3}{proved}{01RD}{the definitions and constructions stated in the proof}

The positive sign region admits the global period chart
\[
 \mathcal O_+=\left\{
 (\tau,\mu,\beta)\in\mathbb C^3:
 \operatorname{Im}\tau>0,\quad
 \operatorname{Im}\beta-\frac{6(\operatorname{Im}\mu)^2}
 {\operatorname{Im}\tau}<0\right\},
\]
represented by the period matrix \eqref{wb:pshift:eq:periods}, with
$\beta_c$ replaced by the coordinate $\beta$. Put
$D=\Im\beta-6(\Im\mu)^2/\Im\tau$. In this chart,
\begin{equation}\hypertarget{tag-01OW}{}\label{fam:eq:F-qD}
 q_e(J)=-\frac6D.
\end{equation}
Every admissible period $\Pi_c(z)$ belongs to $\mathcal O_+$, for every
admissible $c$.  Thus this single maximal proper-action open set contains
all the period images in question.
\end{proposition}
